breakdown.example:
一个高质量实现如下：

function scheduler(tasks, limit) {
  return new Promise((resolve, reject) => {
    const total = tasks.length;
    if (total === 0) return resolve([]);
    const results = new Array(total);
    let nextIndex = 0;
    let active = 0;
    let completed = 0;
    let rejected = false;

    function run() {
      if (rejected) return;
      while (active < limit && nextIndex < total) {
        const current = nextIndex++;
        active++;
        Promise.resolve()
          .then(() => tasks[current]())
          .then((res) => {
            results[current] = res;
            active--;
            completed++;
            if (completed === total) resolve(results);
            else run();
          }, (err) => {
            rejected = true;
            reject(err);
          });
      }
    }

    run();
  });
}

核心思路是：results 通过 current 索引直接赋值，因此即使任务完成顺序不同，最终结果也按输入顺序排列。nextIndex 表示下一个待领取的任务下标，active 表示正在执行的任务数。run 中使用 while 一次性填满可用并发槽位。为了让同步抛错也能被捕获，用 Promise.resolve().then(() => tasks[current]()) 包一层，而不是直接调用 tasks[current]()。任务成功后更新 completed，如果等于 total 就 resolve；任务失败时设置 rejected 并 reject，防止后续继续调度造成无意义执行。该实现时间复杂度 O(n)，空间复杂度 O(n)，能处理空数组、limit 大于任务数、limit 小于等于 0 等边界。
